// Compatibility endpoint for browsers that installed the former Chirpy worker.
// Keep this URL available: deleting it would leave old workers controlling cached pages.
self.addEventListener('install', (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(
      names.filter((name) => name.startsWith('chirpy-')).map((name) => caches.delete(name))
    );

    await self.clients.claim();
    await self.registration.unregister();
  })());
});
